const entrada = $input.first().json.body;
const pedido = entrada && typeof entrada === "object" &&
  !Array.isArray(entrada) ? entrada : {};

const {
  producto,
  cantidad,
  disenos,
  anticipacionDias,
  longitudMetros,
  mismoDiseno
} = pedido;

let estado = "pendiente";
let mensaje = "";
let total = null;
let precioUnitario = null;
let descripcion = "";

const dinero = (valor) =>
  valor.toLocaleString("es-MX", {
    style: "currency",
    currency: "MXN"
  });

// Compatibilidad con el formato anterior:
// producto: "plastico" significa plástico personalizado.
const esPicadoNuevo = producto === "picado";
const esPicadoAnterior = producto === "plastico";

const material = esPicadoAnterior
  ? "plastico"
  : pedido.material;

const tipo = esPicadoAnterior
  ? "personalizado"
  : pedido.tipo;

// 1. VALIDACIÓN GENERAL

if (!Number.isInteger(cantidad) || cantidad < 1) {
  estado = "no_disponible";
  mensaje = "💜 Indícanos una cantidad válida.";

} else if (producto === "taza") {

  // 2. TAZAS
  // Prediseñadas: $38 fijas (precio confirmado por Alecz, 2026-11-28).
  // Personalizadas: $70, o $38 a partir de 12 con el mismo diseño.

  if (tipo === "predisenada") {

    descripcion = `${cantidad} taza(s) prediseñada(s)`;

    if (cantidad >= 100) {
      mensaje =
        "💜 Para pedidos de 100 tazas o más manejamos " +
        "cotizaciones especiales. Karo revisará tu solicitud.";

    } else {
      precioUnitario = 38;
      total = cantidad * precioUnitario;
      estado = "cotizado";
    }

  } else {

    descripcion = `${cantidad} taza(s) personalizada(s)`;

    if (cantidad >= 100) {
      mensaje =
        "💜 Para pedidos de 100 tazas o más manejamos " +
        "cotizaciones especiales. Karo revisará tu solicitud.";

    } else if (cantidad >= 12) {

      if (mismoDiseno !== true) {
        mensaje =
          "💜 Para aplicar el precio por volumen, " +
          "todas las tazas deben tener exactamente " +
          "el mismo diseño. Karo revisará tu solicitud.";

      } else {
        precioUnitario = 38;
        total = cantidad * precioUnitario;
        estado = "cotizado";
      }

    } else {
      precioUnitario = 70;
      total = cantidad * precioUnitario;
      estado = "cotizado";
    }

  }

} else if (esPicadoNuevo || esPicadoAnterior) {

  // 3. PAPEL O PLÁSTICO PICADO

  if (!["papel", "plastico"].includes(material)) {
    mensaje =
      "💜 Indícanos si deseas papel o plástico picado.";

  } else if (!["predisenado", "personalizado"].includes(tipo)) {
    mensaje =
      "💜 Indícanos si deseas picado prediseñado " +
      "o personalizado.";

  } else {

    const nombreMaterial =
      material === "papel" ? "papel" : "plástico";

    descripcion =
      `${cantidad} tira(s) de ${nombreMaterial} ` +
      `picado ${tipo === "predisenado"
        ? "prediseñado"
        : "personalizado"}`;

    if (tipo === "predisenado") {

      // 3A. PICADO PREDISEÑADO

      if (longitudMetros !== undefined &&
          (!Number.isFinite(longitudMetros) ||
           longitudMetros !== 5)) {
        mensaje =
          "💜 Las tiras con longitud especial " +
          "requieren cotización de Karo.";

      } else if (cantidad >= 100) {
        mensaje =
          "💜 Para pedidos de 100 tiras o más " +
          "de picado prediseñado, Karo revisará " +
          "una cotización especial.";

      } else {
        precioUnitario = cantidad >= 10 ? 38 : 40;
        total = cantidad * precioUnitario;
        estado = "cotizado";
      }

    } else {

      // 3B. PICADO PERSONALIZADO

      if (
        cantidad < 10 ||
        cantidad > 100 ||
        cantidad % 10 !== 0
      ) {
        estado = "no_disponible";

        if (cantidad < 10) {
          mensaje =
            "💜 El pedido mínimo es de 10 tiras. " +
            "¿Te gustaría solicitar 10?";

        } else if (cantidad > 100) {
          mensaje =
            "💜 El catálogo estándar contempla " +
            "hasta 100 tiras. Karo puede revisar " +
            "tu solicitud si necesitas más.";

        } else {
          const menor =
            Math.floor(cantidad / 10) * 10;
          const mayor =
            Math.ceil(cantidad / 10) * 10;

          mensaje =
            `💜 No podemos elaborar ${cantidad} tiras. ` +
            "Trabajamos en múltiplos de 10. " +
            `¿Prefieres ${menor} o ${mayor} tiras?`;
        }

      } else {

        const maxDisenos =
          cantidad === 100 ? 5 :
          cantidad >= 50 ? 3 :
          cantidad >= 30 ? 2 : 1;

        if (
          !Number.isInteger(disenos) ||
          disenos < 1 ||
          disenos > maxDisenos
        ) {
          estado = "no_disponible";
          mensaje =
            `💜 Para ${cantidad} tiras se permiten ` +
            `hasta ${maxDisenos} diseño(s). ` +
            "¿Te gustaría ajustar tu pedido?";

        } else if (
          !Number.isFinite(longitudMetros) ||
          longitudMetros !== 5
        ) {
          mensaje =
            "💜 Las tiras con longitud especial " +
            "requieren cotización de Karo.";

        } else if (
          !Number.isFinite(anticipacionDias) ||
          anticipacionDias < 25
        ) {
          mensaje =
            "💜 Los pedidos personalizados requieren " +
            "al menos 25 días de anticipación. " +
            "Karo revisará la disponibilidad.";

        } else {
          precioUnitario =
            cantidad === 100 ? 45 :
            cantidad >= 30 ? 55 : 85;

          total = cantidad * precioUnitario;
          estado = "cotizado";
        }
      }
    }
  }

} else if (producto === "papel_muertos") {

  // 4. PAPEL PICADO DÍA DE MUERTOS
  // Hojas sueltas desde 1 pieza

  const precios = {
    octavo: {
      unitario: 1.50,
      paquete100: 100
    },
    cuarto: {
      unitario: 2.00,
      paquete100: 120
    },
    medio: {
      unitario: 3.00,
      paquete100: 145
    }
  };

  const tamano = pedido.tamano;
  const precio = Object.prototype.hasOwnProperty.call(
    precios, tamano
  ) ? precios[tamano] : null;

  if (!precio) {
    mensaje =
      "💜 Indícanos el tamaño de las hojas: " +
      "octavo, cuarto o medio.";

  } else if (cantidad > 100) {
    mensaje =
      "💜 Para pedidos de más de 100 hojas " +
      "de Día de Muertos, Karo revisará " +
      "una cotización especial.";

  } else {
    if (cantidad === 100) {
      total = precio.paquete100;
      precioUnitario = total / cantidad;
    } else {
      precioUnitario = precio.unitario;
      total = cantidad * precioUnitario;
    }

    descripcion =
      `${cantidad} hoja(s) de papel picado ` +
      `Día de Muertos, tamaño ${tamano}`;

    estado = "cotizado";
  }

} else {
  mensaje =
    "💜 Este producto todavía no tiene una " +
    "cotización automática configurada. " +
    "Karo revisará tu solicitud.";
}

// 5. ANTICIPO GENERAL TAC: 60 %

const anticipo =
  total === null
    ? null
    : Math.round(total * 0.60 * 100) / 100;

const restante =
  total === null
    ? null
    : Math.round((total - anticipo) * 100) / 100;

// 6. MENSAJE PARA EL CLIENTE

if (estado === "cotizado") {
  mensaje =
    "¡Gracias por elegir Todo Artesanal Chiapas! 💜\n\n" +
    `Producto: ${descripcion}\n` +
    `Precio por pieza: ${dinero(precioUnitario)}\n` +
    `Total: ${dinero(total)}\n` +
    `Anticipo del 60 %: ${dinero(anticipo)}\n` +
    `Restante del 40 %: ${dinero(restante)}\n\n` +
    "Cotización sujeta a confirmación de disponibilidad.";
}

return [{
  json: {
    pedido,
    estado,
    precioUnitario,
    total,
    anticipo,
    restante,
    mensaje
  }
}];
